      gist: '广东肇庆法院近日审结一案：男子成某与女友恋爱期间拍摄并保存其多个私密视频及照片，分手后先后50多次以发布网络为要挟，迫使前女友吴某转账共计9766.5元；法院以敲诈勒索罪判处成某有期徒刑一年三个月，并处罚金1万元，责令退赔损失，二审维持原判。法官提醒情侣提高隐私保护意识，遇侵害应及时报警。',
