          body:'<b>法律</b>保护的是每个人的人身与人格权利，不因“曾是恋人”而豁免。以公开私密影像相要挟索取财物，本质是借亲密关系积累的权力不对等实施敲诈——法律把这种行为明确为犯罪，正是为了划清“亲密”与“侵害”的边界，保护弱势一方。',
