      essayQuote: '50多次威胁、9766.5元——数字不大，却足以把一段亲密关系异化成犯罪的现场。法院以敲诈勒索罪判处实刑，释放的信号很清楚：恋爱不是违法的护身符，私密影像更不是要挟的筹码。真正该被提醒的，是那些因羞耻而选择沉默的人——取证、报警，才是把主动权拿回来的第一步。',
