        {t:'“1.8亿婚车”', x:'安徽芜湖新人提前10天订下G7722次高铁同车厢接亲，被网友笑称坐上“价值1.8亿的全球最贵婚车”，两篮喜糖发遍全车。'},
        {t:'婚俗新观念', x:'年轻人用高铁、公交、单车接亲，不再攀比车队长度与酒店排场，把婚礼变成与陌生人分享的温暖旅程。'}
