          naive:'以为大家爱看热闹。',
          lens:'注意力经济', lensId:'attention_economy',
          body:'<b>注意力经济</b>里，反套路的真诚最容易脱颖而出。当豪华婚礼已成视觉疲劳，一列高铁上陌生人接喜糖的微小善意反而击中人心——它用极低的“表演成本”撬动了极高的共情，说明在注意力稀缺的时代，真实比排场更值钱。',
