      theories: [{id:'family',label:'家庭'},{id:'attention_economy',label:'注意力经济'}],
      essayQuote: '“1.8亿的婚车，人均车票86块。”这届年轻人用高铁、公交甚至单车接亲，把婚礼从面子工程还原成一场与陌生人分享的温暖旅程。当豪车长队不再等于幸福厚度，婚俗便悄悄完成一次温柔的革命：最好的仪式感，不是最贵的排场，而是把喜悦分给同行者的那份坦诚。',
