        {t:'路径研判', x:'目前位于那霸偏东约1610公里，向偏西移动；6日前对我国近海无影响，6至7日穿过琉球移入东海。'},
        {t:'两种可能', x:'一是在长江口到福建北部登陆，给浙闽赣强风雨；二是东海转偏北影响长江口至山东半岛，华东至辽宁有9至11级大风与强降雨。'}
