          body:'<b>道德风险</b>指一方不必承担自己行为的全部代价时，就会倾向于更冒险的选择。养殖端的药残风险主要由下游消费者和品牌方承担，养殖户却拿到短期增产的好处，这种成本外部化正是"屡禁不止"的根源；把检测、溯源、追责链条收紧，才能把外部成本内部化。',
          aha:'没人替后果买单的地方，就会有人替自己省钱。'
