          body:'<b>行为经济学</b>告诉我们，消费选择远非理性算计，而深受框架与锚定影响。当"0糖0脂"被反复强化、健康成为新的社交货币，人们会系统性地从"高糖"转向"低卡"。学者 Zhai、Li 与 Wang 在《China Economic Review》的研究基于中国城市家庭数据发现，对含糖饮料征税会显著抑制其消费、并轻微带动无糖饮品消费——当下货架上的无糖逆袭，正是这一结构性替代趋势的市场兑现。',
