          body:'<b>新制度主义</b>看到，称号、资质这类"符号"一旦能被低成本批量授予，就会迅速通胀失去公信力。当"大师"遍地走，它不再代表水平，而成了拉高价的营销道具——协会主动撤销，正是制度在自我纠错，把被玩坏的符号重新收紧。',
          aha:'称号一旦能批量发，就不再是荣誉而是标价。'
