          naive:'以为只是行业自律。',
          lens:'文化资本', lensId:'cultural_capital',
          body:'<b>文化资本</b>的价值在于稀缺与可信。当"大师"头衔被随意附在某些商业招牌上，真正手艺人的文化资本反而被稀释、被蹭流量。撤销泛滥称号，等于把文化评价的标尺交还给作品与口碑本身——让资本重新建立在真本事，而不是一纸虚名上。',
          aha:'挤掉水分，手艺人的真本事才显形。'
