        {t:'根因在供给', x:'TrendForce数据显示2026年Q1通用DRAM合约价环比涨93%–98%、Q2再涨58%–63%；AI服务器对HBM、DDR5的巨量需求挤占消费级产能，存储价格一路飙升。'},
        {t:'终端传导', x:'Counterpoint初步数据显示2026年Q2全球智能手机出货同比下滑11%，机构研判高价格局至少延续至2027年，消费者换机周期或进一步拉长。'}
