          body:'<b>福利经济学</b>关心稀缺资源如何公平分配。当老年人口规模居全球之首，养老、医疗、照护就不再是家庭私事，而必须靠制度化的再分配来兜底。养老金广覆盖、助餐点普惠，都是把“长寿”从家庭风险转化为社会共同保障的安排。',
