      id: 4,
      title: '马尔康红旗大桥垮塌调查报告公布：7人被立案侦查，28名公职人员被问责',
      source: '央视网 / 中国网 / 廉洁四川',
      url: 'https://big5.cctv.com/gate/big5/news.cctv.cn/2026/07/31/ARTI5al9MEnEvLwxPNkihxEl260731.shtml',
      kicker: '工程 · 社会学 / 制度',
      gist: '7月31日，四川阿坝马尔康“11·11”红旗大桥垮塌灾害调查报告公布：勘察弄虚作假、违法分包转包等问题暴露，7名涉案人员被立案侦查，28名公职人员被严肃追责问责——一场无人员伤亡的垮塌，照见的是工程建设全链条的责任真空。',
      thread: [
        {t:'灾害回放', x:'2025年11月11日，马尔康红旗大桥后缘山体突发深层滑坡，带动右岸引桥基础移位、桥墩折断倒塌，国道317线中断，因预警及时未造成伤亡。'},
        {t:'调查结论', x:'直接原因为水库诱发型深层滑坡；同时查明勘察单位未依规开展地质勘察、弄虚作假，存在违法分包转包、隐患排查不到位等问题。'},
        {t:'问责落地', x:'7名涉案人员涉工程重大安全事故罪被立案侦查（4人已移送起诉），省、州、企业28名公职人员被追责问责。'}
      ],
      interpretations: [
        {
          q:'为什么一座“没死人”的桥垮了，追责却这么重？',
          naive:'以为没伤亡就不算大事。',
          lens:'法律社会学', lensId:'law',
          body:'<b>法律社会学</b>强调，制度问责的对象不是“后果”本身，而是“应当履职而未履职”的结构性失范。红旗大桥虽无伤亡，但勘察弄虚作假、违法分包转包，击穿的是工程建设的合规底线；追责之重，正是要向整个行业重申：公共安全不能被“侥幸没出事”所豁免。',
          aha:'法律盯住的，往往不是灾难的结果，而是本可拦住灾难却被放过的环节。'
        },
        {
          q:'为什么层层监管之下，造假还能一路过关？',
          naive:'以为有这么多部门把关就万无一失。',
          lens:'新制度主义', lensId:'institutionalism',
          body:'<b>新制度主义</b>提醒我们，制度的有效性不只在“写了什么”，更在“有没有人真的照办”。当勘察、监理、监管各环节都把签字当作流程而非责任，形式主义就会给造假留出口。报告提出的“压实各方主体责任、健全管理机制”，指向的正是把纸面制度变回可追责的真实约束。',
          aha:'制度最怕的，是人人都“走完了流程”，却没人真的“负起了责”。'
        }
      ],
      theories: [
        {id:'law', label:'法律社会学'},
        {id:'institutionalism', label:'新制度主义'}
      ],
      review: { strength:'law', disciplines:['soc'] }
