      id: 5,
      title: '《住房公积金管理条例》迎重大修订：提取扩至装修物业费，覆盖灵活就业者',
      source: '腾讯新闻 / 新华社 / 经济观察网',
      url: 'https://new.qq.com/rain/a/20260731A0CD6H00?refer=cp_1009',
      kicker: '民生 · 社会学 / 经济',
      gist: '7月31日国常会审议通过《国务院关于修改〈住房公积金管理条例〉的决定（草案）》：提取范围拓宽至装修、物业费，个体工商户、非全日制及灵活就业人员可自愿缴存，贷款审批时限由15日缩至10日——一部运行20多年的制度，开始向“新就业群体”和“存量提质”时代转身。',
      thread: [
        {t:'修法通过', x:'7月31日国常会审议通过修订草案，这是条例继1999年颁布、2002年修订后的又一次系统性升级，核心围绕更普惠、更管用、更便捷、更安全。'},
        {t:'四大变化', x:'提取情形由6种扩至9种（新增装修、物业费）；灵活就业人员可自愿参加；贷款审批15日缩至10日；推动异地互认互贷与数字化。'},
        {t:'地方先行', x:'今年以来已有超60城调整公积金政策，从贷款额度、首付比例到提取范围多维发力，为修法积累实践。'}
      ],
      interpretations: [
        {
          q:'为什么公积金这次改革，专门把“灵活就业者”写进去了？',
          naive:'以为公积金只是上班族的单位福利。',
          lens:'福利经济学', lensId:'econ_welfare',
          body:'<b>福利经济学</b>看重制度是否覆盖到最需要、却最容易被漏掉的人。平台经济和新就业形态下，超2亿灵活就业者长期处在公积金制度之外，租房、买房、装修的住房消费压力无处疏导。把这一群体纳入自愿缴存，是把“单位人”的福利，扩展成“就业者”的福利，缩小保障的群体落差。',
          aha:'一项好制度，不该只在你“有单位”时才罩得住你。'
        },
        {
          q:'为什么从“买房”扩展到“装修、物业”，被视作一种转向？',
          naive:'以为公积金就只为买房服务。',
          lens:'社会资本', lensId:'social_capital',
          body:'从社会学看，住房是家庭<b>社会资本</b>与安稳感的锚点。当城市发展从“增量扩张”转向“存量提质”，群众需求从“有没有房”变成“房好不好住”，公积金用途从购房延伸到修房、养房，呼应的是家庭对“稳态生活”的持续投入。制度跟着人的真实生活走，才留得住信任。',
          aha:'当“装修物业”也能提，公积金才从“买房的助攻”变回“过日子的底气”。'
        }
      ],
      theories: [
        {id:'econ_welfare', label:'福利经济学'},
        {id:'social_capital', label:'社会资本'}
      ],
      review: { strength:'econ_welfare', disciplines:['econ'] }
