      id: 6,
      title: '美股AI芯片股史诗级反攻：美光涨18%、SK海力士涨17%，微软财报点燃存储需求',
      source: '证券时报 / 腾讯新闻',
      url: 'https://stcn.com/article/detail/4051345.html',
      kicker: '经济 · 经济学 / 科技',
      gist: '7月30日美股AI产业链暴力反弹：微软财报超预期带动云与AI商业化信心，存储芯片板块集体井喷，美光科技涨18.36%、SK海力士涨17.52%——AI算力需求，正重塑全球半导体供需周期。',
      thread: [
        {t:'财报引爆', x:'微软第四财季Azure云收入同比大增43%，资本开支指引积极，股价单日涨15.51%创2020年来最大涨幅，市值增超3万亿元。'},
        {t:'板块井喷', x:'存储芯片成最强主线：美光涨18.36%、闪迪涨近26%、西部数据涨16%、SK海力士涨17.52%，费城半导体指数涨8.19%终结五连跌。'},
        {t:'逻辑兑现', x:'市场解读为AI算力基建带动的存储增量需求持续兑现，资金重新回流科技硬赛道。'}
      ],
      interpretations: [
        {
          q:'为什么AI一"咳嗽"，全球芯片股就集体"发烧"？',
          naive:'以为股价涨跌只是公司自己的事。',
          lens:'供给与需求', lensId:'econ_supply_demand',
          body:'<b>供给与需求</b>的周期性，在半导体行业表现得尤为剧烈。Tan 与 Mathews 对全球半导体产业的研究梳理出"短缺—涨价—扩产—过剩—跌价"的钟摆规律：全行业投资呈顺周期特征，而敢于在低谷逆周期下注的企业，在下一轮上行期收获最大。本轮AI存储行情，正是需求侧（云巨头资本开支）突然抬升，撞上供给侧（产能爬坡慢）形成的阶段性紧缺——理解这个周期，才知道眼下的狂欢能走多远。',
          aha:'芯片股不是被AI"点亮"的，而是被供需周期这台风扇吹起来的——风停时，谁在裸泳会很清楚。',
          research: { title:'Cyclical industrial dynamics: The case of the global semiconductor industry', authors:'Hao Tan, John A. Mathews', year:2010, venue:'Technological Forecasting and Social Change', url:'https://doi.org/10.1016/j.techfore.2009.08.003', summary:'梳理全球半导体行业"短缺—涨价—扩产—过剩—跌价"的周期规律，发现全行业投资呈顺周期特征，逆周期投资者在下轮上行期获益最大，是判断本轮AI存储行情持续性的关键参照。', fromNode:'econ_supply_demand' }
        },
        {
          q:'AI到底是在"创造就业"还是在"吞噬就业"？',
          naive:'以为AI只会替代人、消灭岗位。',
          lens:'科技社会学', lensId:'technology',
          body:'<b>科技社会学</b>对技术替代从来持"创造—破坏"并存的判断。AI算力狂飙的直接后果，是催生了从芯片制造、液冷数据中心到模型运维的一整条新产业链；但它也同步挤压着可被自动化的中间岗位。关键不在技术本身，而在社会能否为被替代者提供再技能化通道——否则效率红利只会变成结构性失业的别名。',
          aha:'技术从不直接"消灭工作"，它只是把工作重新分配给了准备好的人。'
        }
      ],
      theories: [
        {id:'econ_supply_demand', label:'供给与需求'},
        {id:'technology', label:'科技社会学'}
      ],
      review: { strength:'econ_supply_demand', disciplines:['econ','soc'] }
