      id: 7,
      title: '新就业形态职业伤害保障试点全国推开，累计参保已达2990万人',
      source: '央视网 / 新华社',
      url: 'https://news.cctv.cn/2026/07/02/ARTIiI5BWJwEIiMP1lVhb4Hn260702.shtml',
      kicker: '劳动 · 经济学 / 社会',
      gist: '7月1日起，新就业形态人员职业伤害保障试点在全国31个省份全面推开，覆盖出行、即时配送、同城货运三大行业；截至6月底累计参保2990.2万人——"按单必保"正在绕过劳动关系，为平台劳动者织一张新安全网。',
      thread: [
        {t:'制度扩围', x:'人社部等9部门部署，自2026年7月1日起试点扩至全国31省份及新疆兵团，新增多家出行、即时配送平台主体。'},
        {t:'机制创新', x:'采取按日参保、按单计费、月度缴费、总参总保，不要求劳动者与平台建立劳动关系，由平台企业按单缴费。'},
        {t:'保障成效', x:'截至2026年6月底累计参保2990.2万人；货拉拉试点累计投保2亿多元，覆盖280万司机、赔付超2800例。'}
      ],
      interpretations: [
        {
          q:'没有劳动合同，骑手外卖员就活该"受伤没保障"吗？',
          naive:'以为没有劳动关系，就不能享受任何工伤保护。',
          lens:'劳动力市场', lensId:'econ_labor',
          body:'<b>劳动力市场</b>的深刻变化，是传统"单位—雇员"框架越来越装不下零工经济。梁栋2026年的研究系统比较了"纳入工伤保险""商业保险"与"新建职业伤害保险"三种模式，论证按单缴费、超越劳动关系束缚的新职伤制度最贴合平台就业特点。2990万人参保的全国推开，正是这套"按单必保"设计的落地——保障重心从"你是否签了合同"转向"你是否真的在承担职业风险"。',
          aha:'劳动保护不必先证明"你是谁的人"，只要证明"你在承担这份险"，就该被兜住。',
          research: { title:'新业态从业者职业伤害保险的模式选择与制度建构', authors:'梁栋', year:2026, venue:'山东大学学报（哲学社会科学版）2026年第1期', url:'https://www.journal.sdu.edu.cn/__local/5/CD/56/BA7099C747383FCC8E547E56AB3_64A90E69_A59AE.pdf', summary:'系统比较"纳入工伤保险""商业保险""新建职业伤害保险"三种模式，论证按单缴费、超越劳动关系束缚的新职伤制度最贴合平台就业特点，此次全国推开即该制度设计落地。', fromNode:'econ_labor' }
        },
        {
          q:'为什么"按单计费"比"签合同"更适合外卖骑手？',
          naive:'以为保障越"正式"越好。',
          lens:'工作社会学', lensId:'work',
          body:'<b>工作社会学</b>看到，平台劳动的核心特征是流动性强、跨平台接单、按单计酬——固定的劳动关系反而是例外。把保障绑定到"每一单"而非"每一份合同"，等于顺着工作的真实形态去设计制度。它标志着劳动保护的理念，从"先定性身份再给权利"，转向"先识别风险再补安全"。',
          aha:'制度追赶现实的速度，决定了打工人是否被时代落下。'
        }
      ],
