      kicker: '文化 · 社会学 / 经济',
      gist: '截至7月30日，2026暑期档电影总票房突破65亿元，动画电影《八仙！》上映十余天近10亿；"电影+文旅"带动下，取景地游客量明显上涨——银幕热度正在变成城市消费增量。',
      thread: [
        {t:'票房走高', x:'网络平台数据：暑期档总票房（含预售）突破65亿元，超120部影片上映；动画《八仙！》凭东方美学与幽默叙事成黑马，票房近10亿。'},
        {t:'取景地效应', x:'《八仙！》带火四川青城山、山东蓬莱阁、山西永乐宫等取景地；温情片《给阿嬷的情书》拉动汕头、潮州侨乡打卡，老厝民宿订单同步上涨。'},
        {t:'政策赋能', x:'国家电影局"2026电影经济促进年"推出首批16个"电影+"消费试点城市，今年以来电影全产业链产值已超3400亿元。'}
      ],
      interpretations: [
        {
          q:'一部动画片，凭什么让千里之外的景区排队的人变多？',
          naive:'以为看电影和去旅游是两回事。',
          lens:'媒介社会学', lensId:'media',
          body:'<b>媒介社会学</b>把电影视为"意义的空间化"——银幕上的蓬莱、青城山被赋予了情感与想象，观众便想去"实地确认"那份体验。杨继军2022年的研究匹配2000—2018年中国上映电影与取景城市数据，发现"涉影城市"旅游收入平均提高8.98%，票房每增10%还能再拉动旅游收入0.41%。这为"电影+文旅"提供了量化依据：银幕热度确实能转化为城市消费。',
          aha:'电影卖出的不只是票，而是一张通往某座城市的"情感车票"。',
          research: { title:'电影、信号强度与旅游业增长', authors:'杨继军（南京财经大学国际经贸学院）', year:2022, venue:'《世界经济》2022年第5期', url:'https://www.ncpssd.cn/Literature/articleinfo?id=SJJJ2022005010&type=journalArticle', summary:'匹配2000—2018年中国上映电影与取景城市数据，发现"涉影城市"旅游收入平均提高8.98%，票房每增10%还能再拉动旅游收入0.41%，为"电影+文旅"联动提供量化依据。', fromNode:'media' }
        },
        {
          q:'为什么我们明知道是"营销"，还是忍不住想去打卡？',
          naive:'以为消费决策完全理性。',
          lens:'注意力经济', lensId:'attention_economy',
          body:'<b>注意力经济</b>下，稀缺的不是商品而是注意力。电影用两小时把一座小城"焊"进公众视野，文旅部门顺势接棒发护照、给折扣，是把已被聚拢的注意力迅速变现。观众以为自己在"追随热爱"，其实正处在一个精心设计的注意力接力里——这无所谓好坏，但看清链路，你才不会被节奏带着跑。',
          aha:'你追逐的"网红地"，往往先被资本追到了你的眼前。'
        }
      ],
