          body:'<b>贝克的风险社会理论</b>指出，现代灾害的后果从来不是纯自然的：建筑抗震标准、预警系统、避难动员、灾后保险，都是社会预先"写好"的风险剧本。日本高度制度化的防灾体系把伤亡压到远低于同级别地震的世界均值，但把尖端产业高度集聚在地震带上，又是现代社会自己制造的新风险。风险从来都是被社会分配和放大的。',
