          body:'<b>道德风险理论</b>指出，风险应由最有能力防范它的一方承担，否则防范激励就会错位：平台掌握风控数据与技术，却把免密支付设为默认开通，等于享受了交易转化率的收益、把盗刷尾部风险留给用户。"先行垫付+异常拦截"之所以是正解，正是因为它把损失压回了防控能力最强的一方，倒逼平台把安全做进产品默认值。',
