          lens:'科技社会学', lensId:'technology',
          body:'<b>科技社会学</b>视角下，支付基础设施的每处"便利设计"都会被黑产当作攻击面来研究：凌晨是人的注意力盲区，小额免密是风控的宽容区，木马劫持验证码则绕过了"手机即本人"的制度假设。技术系统的安全边界从来不是纯技术问题，而是设计者对"正常使用者"的社会想象——黑产恰恰专攻这套想象的缝隙。',
